import{getSpesificAyahService}from"../../../../services/ayah.services.js";const getSpesificAyahController=async(req,res,next)=>{const getSpesificAyah=await getSpesificAyahService(req.params.ayah,req.query);return res.status(200).json({success:true,message:req.ext.constants.MESSAGE_DATA_RETRIEVED,data:getSpesificAyah})};const getRandomAyahController=async(req,res,next)=>{const randomAyahSequence=Math.floor(Math.random()*6236)+1;const getSpesificAyah=await getSpesificAyahService(randomAyahSequence,req.query);return res.status(200).json({success:true,message:req.ext.constants.MESSAGE_DATA_RETRIEVED,data:getSpesificAyah})};export{getRandomAyahController,getSpesificAyahController};